package forth

import (
	"errors"
	"strconv"
	"strings"
)

// prim is a single primitive operation on the stack.
type prim func(stack []int) ([]int, error)

func binary(f func(a, b int) (int, error)) prim {
	return func(s []int) ([]int, error) {
		if len(s) < 2 {
			return nil, errors.New("not enough values on the stack")
		}
		b := s[len(s)-1]
		a := s[len(s)-2]
		r, err := f(a, b)
		if err != nil {
			return nil, err
		}
		return append(s[:len(s)-2], r), nil
	}
}

var builtins = map[string]prim{
	"+": binary(func(a, b int) (int, error) { return a + b, nil }),
	"-": binary(func(a, b int) (int, error) { return a - b, nil }),
	"*": binary(func(a, b int) (int, error) { return a * b, nil }),
	"/": binary(func(a, b int) (int, error) {
		if b == 0 {
			return 0, errors.New("division by zero")
		}
		return a / b, nil
	}),
	"dup": func(s []int) ([]int, error) {
		if len(s) < 1 {
			return nil, errors.New("empty stack")
		}
		return append(s, s[len(s)-1]), nil
	},
	"drop": func(s []int) ([]int, error) {
		if len(s) < 1 {
			return nil, errors.New("empty stack")
		}
		return s[:len(s)-1], nil
	},
	"swap": func(s []int) ([]int, error) {
		if len(s) < 2 {
			return nil, errors.New("not enough values on the stack")
		}
		s[len(s)-1], s[len(s)-2] = s[len(s)-2], s[len(s)-1]
		return s, nil
	},
	"over": func(s []int) ([]int, error) {
		if len(s) < 2 {
			return nil, errors.New("not enough values on the stack")
		}
		return append(s, s[len(s)-2]), nil
	},
}

func isNumber(s string) bool {
	if s == "" {
		return false
	}
	i := 0
	if s[0] == '-' {
		i = 1
	}
	if i == len(s) {
		return false
	}
	for ; i < len(s); i++ {
		if s[i] < '0' || s[i] > '9' {
			return false
		}
	}
	return true
}

func resolve(tokens []string, dict map[string][]prim) ([]prim, error) {
	var def []prim
	for _, tok := range tokens {
		if isNumber(tok) {
			n, _ := strconv.Atoi(tok)
			def = append(def, func(s []int) ([]int, error) {
				return append(s, n), nil
			})
		} else {
			d, ok := dict[strings.ToLower(tok)]
			if !ok {
				return nil, errors.New("undefined operation")
			}
			def = append(def, d...)
		}
	}
	return def, nil
}

func exec(def []prim, stack []int) ([]int, error) {
	for _, p := range def {
		var err error
		stack, err = p(stack)
		if err != nil {
			return nil, err
		}
	}
	return stack, nil
}

func Forth(input []string) ([]int, error) {
	stack := []int{}
	dict := map[string][]prim{}
	for name, p := range builtins {
		dict[name] = []prim{p}
	}

	for _, line := range input {
		tokens := strings.Fields(line)
		for len(tokens) > 0 {
			tok := tokens[0]
			switch {
			case tok == ":":
				if len(tokens) < 4 {
					return nil, errors.New("malformed definition")
				}
				name := strings.ToLower(tokens[1])
				if isNumber(tokens[1]) {
					return nil, errors.New("cannot redefine a number")
				}
				end := -1
				for i := 2; i < len(tokens); i++ {
					if tokens[i] == ";" {
						end = i
						break
					}
				}
				if end == -1 {
					return nil, errors.New("missing ; in definition")
				}
				def, err := resolve(tokens[2:end], dict)
				if err != nil {
					return nil, err
				}
				dict[name] = def
				tokens = tokens[end+1:]
			case isNumber(tok):
				n, _ := strconv.Atoi(tok)
				stack = append(stack, n)
				tokens = tokens[1:]
			default:
				def, ok := dict[strings.ToLower(tok)]
				if !ok {
					return nil, errors.New("undefined operation")
				}
				var err error
				stack, err = exec(def, stack)
				if err != nil {
					return nil, err
				}
				tokens = tokens[1:]
			}
		}
	}
	return stack, nil
}

